INSERT INTO RESTENDPOINTS (ID,"PATH","SEQUENCE",VERB,SUMMARY,DESCRIPTION,STATEMENTTYPE,DATASOURCE,"STATEMENT",ONERECORD,"SOURCE",ALIAS,AUTHORIZATIONREQUIRED,ROLES,CONTROLLERNAME,APPNAME,TRACED,PRECONDITION,VALIDATIONS,RECORDSTATUS,COMPANYID,UPDATEUSERCODE,UPDATEDATE) VALUES (105,'Policy/{id}/Premiums',5,'GET','Recibos pendiente de una p?liza',NULL,'SELECT',2,'SELECT COD_CIA, NUM_POLIZA, NUM_SPTO, NUM_APLI, NUM_SPTO_APLI, NUM_CUOTA, NUM_RECIBO, TIP_RECIBO, FEC_EFEC_RECIBO, FEC_VCTO_RECIBO, TIP_GESTOR, COD_GESTOR, FEC_EMISION_SPTO, TIP_SITUACION, TIP_REMESA, FEC_REMESA, FEC_CTABLE, FEC_VALOR, COD_MON, VAL_CAMBIO, IMP_RECIBO, IMP_NETA, IMP_RECARGO, IMP_IMPTOS, IMP_BONI, IMP_COMIS, TIP_COASEGURO, COD_NIVEL3, COD_AGT, NUM_IMPRESION, CTRL_MOROSO, TXT_AUX1, TXT_AUX2, FEC_ACTU, IMP_TOTAL_COMIS, MCA_CA, MCA_CV, NUM_AVISO, TIP_DOCUM_PAGO, COD_DOCUM_PAGO, IMP_INTERES, IMP_IMPTOS_INTERES, NUM_MVTO_CV, MCA_DCTO_COMIS, FEC_VCTO_PAGO, NUM_MVTO_CA, MCA_DTO_IMPTO, MCA_DTO_RECARGO
  FROM TRON2000.A2990700 a
 WHERE a.NUM_POLIZA={ID:VARCHAR2.13:Required}
   AND a.num_spto IN (select max(aa.num_spto) from a2000030 aa JOIN a2990700 t on t.cod_cia = aa.cod_cia and t.num_poliza = aa.num_poliza and t.num_spto = aa.num_spto and t.num_apli = aa.num_apli and t.num_spto_apli = aa.num_spto_apli and t.tip_situacion = ''EP'' where aa.cod_cia  = a.cod_cia and aa.num_poliza = a.NUM_POLIZA AND aa.mca_spto_anulado = ''N'')
   AND num_recibo IN (select t.num_recibo from a2990700 t where t.cod_cia = a.cod_cia and t.num_poliza = a.num_poliza and t.num_spto = a.num_spto and t.num_apli = a.num_apli and t.num_spto_apli = a.num_spto_apli and t.tip_situacion = ''EP'')
',0,'Custom','PendingPremiums',1,NULL,'Pólizas','TRON',0,NULL,NULL,1,0,6329,TIMESTAMP'2023-06-13 00:00:00.0');
